import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterAll, describe, expect, it } from 'vitest';

import { MIGRATIONS_FOLDER } from '../migrate.ts';
import { lintMigrationSql, reviewHeader } from '../migration-lint.ts';

const PACKAGE_DIR = fileURLToPath(new URL('../..', import.meta.url));
const HEADER =
  '-- Migration 0001_x: generated by drizzle-kit, hand-reviewed before commit.\n-- Reviewed-by: Asha\n';
const messages = (sqlText: string) =>
  lintMigrationSql('m.sql', sqlText).map((i) => `${String(i.line)}:${i.message}`);

describe('lintMigrationSql', () => {
  it('passes the committed migrations', () => {
    const text = readFileSync(path.join(MIGRATIONS_FOLDER, '0000_baseline.sql'), 'utf8');
    expect(lintMigrationSql('0000_baseline.sql', text)).toEqual([]);
  });

  it('requires a review header with a reviewer', () => {
    expect(messages('CREATE TABLE "a" ("id" int);')).toEqual([
      '1:missing review header (`-- Reviewed-by: <name>`)',
    ]);
    expect(messages(`${reviewHeader('0001_x')}CREATE TABLE "a" ("id" int);`)).toEqual([
      '1:migration has not been reviewed yet',
    ]);
  });

  it.each([
    'DROP TABLE "matter";',
    'drop table if exists matter cascade;',
    'ALTER TABLE "matter" DROP COLUMN "title";',
    'ALTER TABLE "a" ADD COLUMN "b" int;--> statement-breakpoint\nALTER TABLE "matter" DROP COLUMN "title";--> statement-breakpoint',
  ])('rejects an unannotated destructive statement: %s', (statement) => {
    const issues = lintMigrationSql('m.sql', HEADER + statement);
    expect(issues).toHaveLength(1);
    expect(issues[0]?.message).toMatch(/destructive statement without `-- contract:approved`/);
  });

  it('accepts a destructive statement annotated -- contract:approved', () => {
    expect(
      messages(
        `${HEADER}-- contract:approved (column unused since release 12)\nALTER TABLE "matter" DROP COLUMN "title";`,
      ),
    ).toEqual([]);
    expect(messages(`${HEADER}DROP TABLE "legacy"; -- contract:approved`)).toEqual([]);
  });

  it('scopes an approval to one statement', () => {
    const text = `${HEADER}-- contract:approved\nDROP TABLE "a";--> statement-breakpoint\nDROP TABLE "b";`;
    expect(messages(text)).toEqual([
      '5:destructive statement without `-- contract:approved` (expand/contract: drop only in a contract migration)',
    ]);
  });

  it('ignores DROP inside comments and non-destructive drops', () => {
    expect(
      messages(
        `${HEADER}-- we never DROP TABLE here\nDROP INDEX "x";\nALTER TABLE "a" DROP CONSTRAINT "c";`,
      ),
    ).toEqual([]);
  });
});

describe('lint-migrations CLI', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'causedeck-lint-'));
  afterAll(() => {
    rmSync(dir, { recursive: true, force: true });
  });
  const run = (...args: string[]) =>
    spawnSync('pnpm', ['exec', 'tsx', 'scripts/lint-migrations.ts', ...args], {
      cwd: PACKAGE_DIR,
      encoding: 'utf8',
    });

  it('passes the committed migrations', () => {
    const result = run();
    expect(result.status, result.stderr).toBe(0);
  });

  it('fails a migration folder with an unapproved DROP TABLE', () => {
    writeFileSync(path.join(dir, '0001_drop.sql'), `${HEADER}DROP TABLE "matter";\n`);
    const result = run('--dir', dir);
    expect(result.status).toBe(1);
    expect(result.stderr).toContain('0001_drop.sql:3 destructive statement');
  });

  it('--stamp adds the placeholder header, which then fails until reviewed', () => {
    const file = path.join(dir, '0002_new.sql');
    writeFileSync(file, 'CREATE TABLE "a" ("id" int);\n');
    expect(run('--dir', dir, '--stamp').status).toBe(0);
    expect(readFileSync(file, 'utf8')).toMatch(
      /^-- Migration 0002_new: .*\n-- Reviewed-by: <unreviewed>\nCREATE TABLE/,
    );
    expect(run('--dir', dir).stderr).toContain(
      '0002_new.sql:1 migration has not been reviewed yet',
    );
  });
});
